let currentUnit='cover',currentMode='web';
const modes=['web','pdf','outline','audio'];
function setMode(mode){if(mode==='pdf')mode='web';currentMode=modes.includes(mode)?mode:'web';modes.forEach(x=>document.getElementById(x).hidden=x!==currentMode);document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===currentMode)));filterPages();}
function filterPages(){const n=/^u\d\d$/.test(currentUnit)?Number(currentUnit.slice(1)):null;document.querySelectorAll('[data-unit-page]').forEach(p=>p.hidden=p.dataset.unitPage!==currentUnit);document.querySelectorAll('[data-print-kind]').forEach(p=>{p.hidden=currentUnit!=='cover'&&(n!==null?Number(p.dataset.printLesson)!==n&&!p.dataset.answerLessons.split(',').includes(String(n)):p.dataset.printGroup!==currentUnit)});document.querySelectorAll('[data-audio-unit]').forEach(p=>p.hidden=currentUnit!=='cover'&&p.dataset.audioUnit!==currentUnit);document.querySelectorAll('nav [data-unit]').forEach(b=>b.classList.toggle('active',b.dataset.unit===currentUnit));filterWords();}
function selectUnit(id,scroll=true){currentUnit=id;if(currentMode==='outline'||id==='cover')setMode('web');filterPages();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function goTo(el){requestAnimationFrame(()=>{el.scrollIntoView({block:'start'});el.setAttribute('tabindex','-1');el.focus({preventScroll:true})})}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{setMode(b.dataset.mode);location.hash=currentMode==='web'?currentUnit:currentMode+'-'+currentUnit}));
document.querySelectorAll('[data-unit]').forEach(b=>b.addEventListener('click',()=>{if(b.hasAttribute('data-return-web'))setMode('web');selectUnit(b.dataset.unit);location.hash=currentMode==='web'?b.dataset.unit:currentMode+'-'+b.dataset.unit}));
document.querySelectorAll('.translation').forEach(b=>b.addEventListener('click',()=>{const hide=b.closest('.dialogue').classList.toggle('hide-ko');b.setAttribute('aria-pressed',String(hide));b.textContent=hide?'해석 보기':'해석 가리기';}));
document.querySelectorAll('.hide-meanings').forEach(b=>b.addEventListener('click',()=>{const hide=b.closest('article').classList.toggle('meaning-hidden');b.setAttribute('aria-pressed',String(hide));b.textContent=hide?'뜻 보기':'뜻 가리기'}));
document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(other=>{if(other!==a)other.pause()})));
const player=document.getElementById('main-audio'),bar=document.getElementById('player'),status=document.getElementById('status');
document.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',async()=>{bar.hidden=false;status.textContent=b.textContent.trim();player.src='/api/books/japanese-n5/7f572327dc67893e9453246c/asset?file=audio/'+b.dataset.play+'.mp3';try{await player.play()}catch{status.textContent='재생 버튼을 눌러 주세요.'}}));
document.getElementById('close-player').addEventListener('click',()=>{player.pause();bar.hidden=true});
function hashRoute(){let hash='';try{hash=decodeURIComponent(location.hash.slice(1))}catch{return}const el=document.getElementById(hash),article=el?.closest('[data-unit-page]');
 if(hash.startsWith('audio-u')){currentUnit=hash.slice(6).split('-')[0];setMode('audio');if(el)goTo(el)}
 else if(/^(web|pdf|outline|audio)-(cover|u\d\d|guide|materials|reference)$/.test(hash)){const split=hash.indexOf('-');currentUnit=hash.slice(split+1);setMode(hash.slice(0,split))}
 else if(article){currentUnit=article.dataset.unitPage;if(currentUnit==='reference'&&hash!=='reference-start'){const search=document.getElementById('lex-search');search.value=''}setMode('web');goTo(el)}
 else if([...document.querySelectorAll('nav [data-unit]')].some(b=>b.dataset.unit===hash)){selectUnit(hash,false);setMode('web')}
 else if(hash.startsWith('toc')){setMode('outline')}
 else if(document.getElementById('pdf-'+hash)){const figure=document.getElementById('pdf-'+hash);currentUnit=figure.dataset.printGroup||(/^\d+$/.test(figure.dataset.printLesson)&&Number(figure.dataset.printLesson)>0?'u'+figure.dataset.printLesson.padStart(2,'0'):'cover');setMode('pdf');goTo(figure)}
 else if(!hash){selectUnit('cover',false)}
}
function filterWords(){const query=(document.getElementById('lex-search')?.value||'').trim().toLowerCase();let matches=0;document.querySelectorAll('.lex-card').forEach(card=>{card.hidden=!!query&&!card.dataset.search.toLowerCase().includes(query);if(!card.hidden)matches++});if(currentUnit==='reference'){document.querySelectorAll('#web article[data-unit-page="reference"]').forEach(p=>{p.hidden=!!query&&!p.querySelector('.lex-card:not([hidden])')})}const label=document.querySelector('.search-status');if(label)label.textContent=query?`${matches}개 단어를 찾았어요.`:''}
document.getElementById('lex-search').addEventListener('input',filterWords);
window.addEventListener('hashchange',hashRoute);hashRoute();filterPages();
const revision=document.querySelector('meta[name="manuscript-revision"]').content;
const draftKey='manabi-n5-'+revision+'-drafts-v1';
let drafts={};try{const parsed=JSON.parse(localStorage.getItem(draftKey)||'{}');if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))drafts=parsed}catch{}
document.querySelectorAll('[data-save]').forEach(el=>{const key=el.dataset.save,value=drafts[key];if(el.type==='radio')el.checked=value===el.value;else if(el.type==='checkbox')el.checked=value===true;else if(typeof value==='string')el.value=value;el.addEventListener('input',()=>{drafts[key]=el.type==='checkbox'?el.checked:el.value;try{localStorage.setItem(draftKey,JSON.stringify(drafts));document.querySelectorAll('.draft-status').forEach(n=>n.textContent='이 판본의 답안을 이 브라우저에 저장했어요.')}catch{document.querySelectorAll('.draft-status').forEach(n=>n.textContent='브라우저 저장을 사용할 수 없어 현재 화면에만 유지돼요.')}})});

